window.CALCULATOR_LESSONS = [{"id":"CT01","title":"Numerical entry, notation and rounding","steps":[{"key":"HOME","screen":"Add Calculator","say":"Open a Calculator page. Group the numerator and denominator before entering a fraction."},{"key":"x10ⁿ","screen":"((4×10^5)×(3×10^−2))/(2×10^3)","say":"Use the scientific notation key for powers of ten. Keep the negative sign inside the exponent."},{"key":"ENTER","screen":"6","say":"Read the unrounded value first. Scientific notation on the screen may use the letter E."},{"key":"WRITE","screen":"6.00 to three significant figures","say":"Show the requested precision in your written answer. Six point zero zero has three significant figures."}],"try":{"prompt":"(3.6 × 10⁵)(2.5 × 10⁻²) ÷ (4.0 × 10³). Enter the result to three significant figures.","answer":2.25,"explain":"Group both factors in the numerator and the full denominator. The exact value is 2.25.","alternatives":[]}},{"id":"CT02","title":"Angle modes and inverse trigonometry","steps":[{"key":"DOC","screen":"Settings & Status → Document Settings","say":"Open Document Settings. Set the angle unit to match the problem."},{"key":"DEGREE","screen":"Angle: Degree","say":"Use Degree when the problem asks for an answer in degrees."},{"key":"TRIG","screen":"sin⁻¹(0.6)","say":"Choose inverse sine, then enter the ratio. Inverse sine returns an angle, not a reciprocal."},{"key":"ENTER","screen":"36.86989765…°","say":"Read the principal angle. Use the problem's angle range to check whether another solution is needed."}],"try":{"prompt":"An acute angle θ satisfies cos θ = 0.4. Find θ in degrees, to one decimal place.","answer":66.4,"explain":"In Degree mode, inverse cosine of 0.4 is about 66.4218°.","alternatives":[]}},{"id":"CT03","title":"Combinations and factorials","steps":[{"key":"HOME","screen":"Add Calculator","say":"Use a combination when order does not matter."},{"key":"MENU","screen":"Probability → Combinations","say":"Open Probability and choose Combinations, or enter nCr from the Catalog."},{"key":"TYPE","screen":"nCr(7,3)","say":"Enter the number available first and the number chosen second."},{"key":"ENTER","screen":"35","say":"The result counts selections, not arrangements. Seven factorial divided by three factorial and four factorial confirms it."}],"try":{"prompt":"There are 9 students in a club. How many different groups of 4 can represent the club if roles are not assigned?","answer":126,"explain":"Order does not matter, so calculate nCr(9,4) = 126.","alternatives":[]}},{"id":"CT04","title":"Sequences, sigma and first threshold","steps":[{"key":"HOME","screen":"Add Calculator","say":"Identify the first index and write one expression for the general term before entering a sum."},{"key":"TEMPLATE","screen":"Σ from k=1 to 5 of 3k+1","say":"Choose the summation template. Assign a variable and fill both index limits."},{"key":"ENTER","screen":"50","say":"The sum includes both endpoints. Here the five terms are four, seven, ten, thirteen, and sixteen."},{"key":"CHECK","screen":"Sum to n−1, then sum to n","say":"For a first threshold, bracket it with successive integer indices, then check that the earlier value has not crossed it."}],"try":{"prompt":"A practice schedule has daily counts 4, 7, 10, 13, …. What is the first day when the cumulative count is at least 55?","answer":6,"explain":"The sum after five days is 50. After six days it is 69, which is the first total at least 55.","alternatives":[]}},{"id":"CT05","title":"Financial mathematics and TVM","steps":[{"key":"MENU","screen":"Finance → Finance Solver","say":"From Calculator, open Finance Solver. Check the stored fields before using them."},{"key":"TAB","screen":"N: 3   I(%): 6   PV: −2000   Pmt: 0","say":"Enter the number of periods and the annual percentage rate. An initial deposit is cash leaving your hands."},{"key":"TAB","screen":"PpY: 1   CpY: 1   PmtAt: END","say":"Set payments per year and compounds per year to one for annual compounding. No regular payments are made."},{"key":"ENTER","screen":"FV: 2382.032","say":"Select the future value field and press Enter. Round to cents only after solving."}],"try":{"prompt":"You deposit 1500 at 4% interest compounded annually, with no later deposits or withdrawals. Find the balance after three years, to the nearest cent.","answer":1687.3,"explain":"Finance Solver uses N=3, I=4, PV=−1500, Pmt=0, PpY=CpY=1. The balance is 1500×1.04³.","alternatives":[]}},{"id":"CT07","title":"Simultaneous equations and unknown parameters","steps":[{"key":"HOME","screen":"Add Calculator","say":"Put the unknowns into the same order in every equation. Move constants to the right."},{"key":"TEMPLATE","screen":"a:= [[2,1],[1,−1]]    b:= [[11],[1]]","say":"Use matrix templates for the coefficients and a column for the constants. Store each matrix with colon equals."},{"key":"CATALOG","screen":"simult(a,b)","say":"Insert simult from the Catalog. It solves the linear system whose coefficient matrix is A."},{"key":"ENTER","screen":"[[4],[3]]","say":"Read the solution in column order. Substitute either value into both original equations to check."}],"try":{"prompt":"Solve 3x + y = 14 and x − y = 2. Enter x.","answer":4,"explain":"Add the equations to get 4x = 16. The solution column is x = 4, y = 2.","alternatives":[]}},{"id":"CT08","title":"Graph setup, zoom and viewing window","steps":[{"key":"HOME","screen":"Add Graphs","say":"Enter the function in the Graphs application and press Enter."},{"key":"TYPE","screen":"f1(x)=(x−12)^2+3","say":"The default window may hide the interesting feature. Here the vertex lies beyond the usual central view."},{"key":"MENU","screen":"Window/Zoom → Window Settings","say":"Set the horizontal and vertical limits independently. A viewing window does not change the domain."},{"key":"ENTER","screen":"xMin: 10   xMax: 14   yMin: 0   yMax: 8","say":"This window contains the vertex with space on both sides. Use your context to choose sensible bounds."}],"try":{"prompt":"For y=(x−15)²+2, which viewing window shows the vertex comfortably inside both axes?","answer":"x: 13 to 17; y: 0 to 8","explain":"The vertex is (15,2). This window contains that point with space around it.","alternatives":[],"choices":["x: −8 to 8; y: 0 to 8","x: 13 to 17; y: 4 to 8","x: 13 to 17; y: 0 to 8"]}},{"id":"CT09","title":"Trace, tables and function values","steps":[{"key":"HOME","screen":"Add Graphs","say":"Enter the function on a Graphs page."},{"key":"MENU","screen":"Trace → Graph Trace","say":"Start Graph Trace. Move the cursor with the arrow keys, or enter a specific x value."},{"key":"TYPE","screen":"f1(x)=2x²−3  at x=3","say":"Type the input value and press Enter. Read both coordinates, not just the number next to the cursor."},{"key":"READ","screen":"(3,15)","say":"The second coordinate is the function value. A function table is useful for checking several inputs in a row."}],"try":{"prompt":"Use a trace or table to find f(−2) for f(x)=3x²−2x+1.","answer":17,"explain":"Substituting −2 gives 3×4 + 4 + 1 = 17.","alternatives":[]}},{"id":"CT10","title":"Zeros and intercepts","steps":[{"key":"HOME","screen":"Graphs: f1(x)=x²−5x+6","say":"Plot the function. A zero is an x value for which the function is zero."},{"key":"MENU","screen":"Analyze Graph → Zero","say":"Open Analyze Graph and choose Zero. If prompted, select the curve to analyze."},{"key":"ENTER","screen":"Lower bound: 1.5   Upper bound: 2.5","say":"Place one bound on each side of the crossing. Keep other zeros outside those bounds."},{"key":"READ","screen":"x ≈ 2   y ≈ 0","say":"Read the x coordinate. For a y-intercept, evaluate the function at x equal to zero instead."}],"try":{"prompt":"Find the larger x-intercept of y=x²−7x+10. Enter its x-coordinate.","answer":5,"explain":"The zeros are 2 and 5. Isolate the larger one with bounds such as 4 and 6.","alternatives":[]}},{"id":"CT11","title":"Intersections of two functions","steps":[{"key":"HOME","screen":"Graphs: f1(x)=x²; f2(x)=2x+3","say":"Plot both functions on the same page. Look for the crossing that matches the requested point."},{"key":"MENU","screen":"Analyze Graph → Intersection","say":"Choose Intersection. Select the relevant graphs if prompted."},{"key":"ENTER","screen":"Lower bound: 2   Upper bound: 4","say":"Bracket one crossing at a time with the lower and upper bounds."},{"key":"READ","screen":"(3,9)","say":"Read the coordinates. At the intersection both expressions give the same y value."}],"try":{"prompt":"The graphs y=x² and y=x+6 intersect twice. Find the x-coordinate of the negative intersection.","answer":-2,"explain":"Solving x²=x+6 gives x=−2 or x=3. The negative intersection is at x=−2.","alternatives":[]}},{"id":"CT13","title":"Graphical inequalities and exclusions","steps":[{"key":"HOME","screen":"Graphs: f1(x)=x²; f2(x)=4","say":"Plot both sides. A graph can help separate intervals where one side lies above or below the other."},{"key":"MENU","screen":"Analyze Graph → Intersection","say":"Find each intersection. Here they occur at negative two and two."},{"key":"CHECK","screen":"f1(0)=0 < 4; f1(3)=9 > 4","say":"Test a point in each interval. Also check for undefined values or excluded endpoints."},{"key":"WRITE","screen":"x² < 4:  −2 < x < 2","say":"Do not include equality for a strict inequality. Points where the expression is undefined never belong."}],"try":{"prompt":"On the real number line, solve x² ≥ 9.","answer":"x ≤ −3 or x ≥ 3","explain":"The parabola is at or above the line y=9 outside the two intersections. Equality includes both endpoints.","alternatives":[],"choices":["−3 ≤ x ≤ 3","x < −3 or x > 3","x ≤ −3 or x ≥ 3"]}},{"id":"CT14","title":"All trigonometric solutions in an interval","steps":[{"key":"MENU","screen":"Graphs → Settings → Graphing Angle: Degree","say":"From Graphs, open Settings and set Graphing Angle to Degree. Graphs has its own angle setting."},{"key":"TYPE","screen":"f1(x)=sin(x); f2(x)=0.5; x-window 0 to 360","say":"Plot both sides. Set the horizontal window to show the entire requested interval."},{"key":"MENU","screen":"Analyze Graph → Intersection","say":"Find each crossing in a separate bracket. One numeric solve or one intersection is not a check for all solutions."},{"key":"READ","screen":"0 ≤ x < 360:  x=30°, 150°","say":"Check the interval endpoints and report every crossing found in the requested interval."}],"try":{"prompt":"In degrees, solve cos x = 0.5 for 0 ≤ x < 360. Which pair gives all the solutions?","answer":"60° and 300°","explain":"Cosine is 0.5 in quadrants one and four, at 60° and 300°.","alternatives":[],"choices":["60° only","60° and 120°","60° and 300°"]}},{"id":"CT15","title":"Piecewise, restricted and transformed graphs","steps":[{"key":"HOME","screen":"Add Graphs · calculator-assisted","say":"Write the formula and its condition together. The calculator draws the branches you specify."},{"key":"TEMPLATE","screen":"Two-piece function template","say":"In the function entry line, open Math Templates and choose the two-piece template."},{"key":"TYPE","screen":"f1: x+2 if x<0; x²+1 if x≥0","say":"Enter both branches and conditions. Make sure the boundary is assigned to the correct branch."},{"key":"ENTER","screen":"At x=0: f1(0)=1","say":"Check the boundary by substitution, even if two branch ends look connected on the screen."}],"try":{"prompt":"Let g(x)=2x+4 for x<1 and g(x)=x²−3 for x≥1. Find g(1).","answer":-2,"explain":"The second condition includes equality, so g(1)=1²−3=−2.","alternatives":[]}},{"id":"CT16","title":"Finding a model threshold","steps":[{"key":"HOME","screen":"Graphs: f1(x)=50·1.1^x; f2(x)=80","say":"Plot the model and a horizontal line at the target. Choose a window that shows the allowed time range."},{"key":"MENU","screen":"Analyze Graph → Intersection","say":"Find the meeting point with bounds around it."},{"key":"ENTER","screen":"x ≈ 4.931","say":"Read the continuous threshold time. Check whether the context accepts fractional values."},{"key":"CHECK","screen":"At x=4: below 80; at x=5: above 80","say":"If only whole periods count, test the consecutive integers around the crossing."}],"try":{"prompt":"The number of seeds in stock follows N(t)=120(0.85)^t. At what first whole day t is the stock below 70?","answer":4,"explain":"N(3)≈73.70 and N(4)≈62.64. The model decreases, so day 4 is the first below 70.","alternatives":[]}},{"id":"CT17","title":"2D/3D lengths, angles and bearings","steps":[{"key":"DOC","screen":"Angle: Degree","say":"Use Degree for ordinary bearings. Sketch the triangle first, including the angle between the given sides."},{"key":"HOME","screen":"Add Calculator","say":"For travel legs seven and eight with an included angle of sixty degrees, use the cosine rule."},{"key":"TYPE","screen":"√(7²+8²−2·7·8·cos(60))","say":"Enter the full cosine-rule expression inside the square root. Use multiplication between factors."},{"key":"ENTER","screen":"√57 ≈ 7.55","say":"The result is a length. Bearings are angles measured clockwise from north, so translate them before substituting."}],"try":{"prompt":"Two paths leave the same point with an included angle of 60°. One path is 5 km long and the other is 9 km long. Find the distance between their ends to three significant figures.","answer":7.81,"explain":"The cosine rule gives √(25+81−45)=√61≈7.81025 km.","alternatives":[]}},{"id":"CT18","title":"Voronoi sites and nearest neighbours","steps":[{"key":"HOME","screen":"Add Calculator · calculator-assisted","say":"The device compares distances. It does not decide how your Voronoi cells are drawn."},{"key":"TYPE","screen":"Compare squared distances from P=(2,1)","say":"Square each horizontal and vertical difference and add. Comparing squared distances gives the same ordering."},{"key":"ENTER","screen":"A=(0,0): 5   B=(5,0): 10","say":"The smaller squared distance identifies the nearer site. Repeat for any other candidate site."},{"key":"CHECK","screen":"Equal squared distances indicate a boundary between the two nearest sites","say":"Check other sites before declaring a Voronoi boundary."}],"try":{"prompt":"Which site is nearest to point (4,2)?","answer":"B (5,3)","explain":"Squared distances to A, B and C are 20, 2 and 9 respectively, so B is nearest.","alternatives":[],"choices":["A (0,0)","B (5,3)","C (4,5)"]}},{"id":"CT19","title":"Vector arithmetic and angles","steps":[{"key":"DOC","screen":"Angle: Degree · calculator-assisted","say":"Write the vector components in matching order. Use Degree if the question asks for degrees."},{"key":"HOME","screen":"Add Calculator","say":"Find the scalar product by multiplying corresponding components and adding."},{"key":"TYPE","screen":"u=(2,1), v=(−1,2): 2·(−1)+1·2","say":"The dot product is zero. With two nonzero vectors, this means they are perpendicular."},{"key":"ENTER","screen":"u·v=0; θ=90°","say":"For a nonzero dot product, divide it by the product of the lengths before taking inverse cosine."}],"try":{"prompt":"Find the scalar product of u=(3,−2,4) and v=(2,5,1).","answer":0,"explain":"Pair components in order: 3·2+(−2)·5+4·1=0.","alternatives":[]}},{"id":"CT20","title":"Complex numbers: rectangular and polar","steps":[{"key":"DOC","screen":"Document Settings: Rectangular; Angle: Degree","say":"Set the complex format to Rectangular for a plus b i. Set Degree if the argument is requested in degrees."},{"key":"HOME","screen":"Add Calculator","say":"Insert the imaginary unit from the symbols palette or Catalog, not as an ordinary variable."},{"key":"CATALOG","screen":"abs(3+4i); angle(3+4i)","say":"Use absolute value for modulus and angle for argument. Check the argument unit and quadrant."},{"key":"ENTER","screen":"r=5; θ≈53.1301°","say":"The modulus is nonnegative. Convert the principal argument only if the problem asks for another range."},{"key":"DOC","screen":"Real or Complex: Polar · r=5, θ≈53.13°","say":"For polar display, change Real or Complex to Polar and re-enter the original complex number. The number itself has not changed."}],"try":{"prompt":"Find the modulus of z=−5+12i.","answer":13,"explain":"The modulus is the distance from the origin: √(25+144)=13.","alternatives":[]}},{"id":"CT21","title":"Matrices: entry, determinant and inverse","steps":[{"key":"HOME","screen":"Add Calculator","say":"Matrix dimensions matter. Use the matrix template to enter rows and columns in the order shown."},{"key":"TEMPLATE","screen":"a:= [[2,1],[3,4]]","say":"A two by two matrix needs two rows and two columns. Store each matrix with colon equals."},{"key":"CATALOG","screen":"det(a) = 5","say":"Use det to check whether the square matrix is invertible. A zero determinant means no inverse."},{"key":"ENTER","screen":"a^−1 = [[0.8,−0.2],[−0.6,0.4]]","say":"Raise the matrix to negative one for its inverse. A times its inverse should give the identity. Use Control Enter if you need decimals."}],"try":{"prompt":"Find the determinant of the matrix with rows (4,1) and (3,5).","answer":17,"explain":"The determinant is 4×5−1×3=17.","alternatives":[]}},{"id":"CT22","title":"Matrix transformations of coordinates","steps":[{"key":"HOME","screen":"Add Calculator","say":"Use column vectors for points unless your question specifies another convention."},{"key":"TEMPLATE","screen":"t:= [[0,−1],[1,0]]; p:= [[3],[2]]","say":"Enter the transformation matrix and the point as a two by one column. Store each matrix with colon equals."},{"key":"TYPE","screen":"t·p","say":"Multiply the transformation matrix by the point. Changing the order changes the meaning or gives a dimension error."},{"key":"ENTER","screen":"[[-2],[3]]","say":"This matrix rotates a point ninety degrees counterclockwise about the origin."}],"try":{"prompt":"Use the transformation matrix with rows (1,2) and (0,1) on the point (3,4) written as a column. Enter the x-coordinate of the image.","answer":11,"explain":"The first row produces 1×3+2×4=11. The image is (11,4).","alternatives":[]}},{"id":"CT23","title":"Solve linear systems using matrices","steps":[{"key":"HOME","screen":"Add Calculator","say":"Write the equations as A times the unknown column equals the constants column."},{"key":"TEMPLATE","screen":"a:= [[1,2],[3,1]]; b:= [[9],[7]]","say":"Use the same variable order for both rows. Put one constant beside each equation. Store each matrix with colon equals."},{"key":"CATALOG","screen":"det(a)=−5","say":"Check that A is invertible. If the determinant is zero, this inverse method does not apply."},{"key":"ENTER","screen":"a^−1·b = [[1],[4]]","say":"Multiply the inverse by the constants column in that order. The first entry corresponds to the first variable."}],"try":{"prompt":"Solve x+2y=11 and 3x+y=13 by a matrix method. Enter y.","answer":4,"explain":"The solution is x=3 and y=4. In matrix form, A⁻¹b gives that two-entry column.","alternatives":[]}},{"id":"CT24","title":"Transition matrices and Markov chains","steps":[{"key":"HOME","screen":"Add Calculator","say":"Check whether the question uses row or column state vectors. This example uses a column."},{"key":"TEMPLATE","screen":"p:= [[0.8,0.3],[0.2,0.7]]; s:= [[1],[0]]","say":"Put the origin states in the columns. A column must sum to one because it lists all destinations. Store each matrix with colon equals."},{"key":"ENTER","screen":"p·s = [[0.8],[0.2]]","say":"Multiplying gives the distribution after one transition. For two transitions use P squared."},{"key":"CHECK","screen":"p²·s = [[0.70],[0.30]]","say":"The entries still sum to one. Read the entry for the requested state and time."}],"try":{"prompt":"Use the column-stochastic matrix P with rows (0.7,0.2) and (0.3,0.8). Starting in state A with column (1,0), what is the probability of state B after two transitions?","answer":0.45,"explain":"After one step the vector is (0.7,0.3). Its next B probability is 0.3×0.7+0.8×0.3=0.45.","alternatives":[]}},{"id":"CT25","title":"Eigenvalues and long-run behaviour","steps":[{"key":"HOME","screen":"Add Calculator · calculator-assisted","say":"For a two by two matrix, eigenvalues solve its characteristic equation. The calculator can evaluate the coefficients."},{"key":"TEMPLATE","screen":"a:= [[3,2],[1,4]]","say":"Add the diagonal entries for the trace. Use det for the determinant. Store each matrix with colon equals."},{"key":"TYPE","screen":"trace=7; det(a)=10","say":"Form lambda squared minus trace times lambda plus determinant, then set that expression equal to zero."},{"key":"ENTER","screen":"λ²−7λ+10=0:  λ=2 or 5","say":"Find the two roots. In a repeated matrix model, check the model assumptions before inferring long-run behaviour from the largest absolute value."}],"try":{"prompt":"Find the larger eigenvalue of the matrix with rows (2,1) and (3,4).","answer":5,"explain":"Trace is 6 and determinant is 5, so the characteristic equation has roots 1 and 5.","alternatives":[]}},{"id":"CT26","title":"Adjacency matrices and walks","steps":[{"key":"HOME","screen":"Add Calculator","say":"Write the vertex order first. In this example rows give the origin and columns give the destination."},{"key":"TEMPLATE","screen":"Vertices A,B,C · m:=[[0,1,0],[1,0,1],[0,1,0]]","say":"The edges join A to B and B to C. Enter each adjacency row in that order. Store each matrix with colon equals."},{"key":"TYPE","screen":"m² = [[1,0,1],[0,2,0],[1,0,1]]","say":"Square the matrix to count walks of exactly two steps. A walk can revisit a vertex."},{"key":"READ","screen":"Entry A,C = 1","say":"This entry counts walks from A to C. It is not a distance or a count of shortest routes."}],"try":{"prompt":"An undirected network has edges A–B and B–C only. How many walks of exactly three steps go from A to B?","answer":2,"explain":"The walks are A–B–A–B and A–B–C–B. Read row A, column B in M³.","alternatives":[]}},{"id":"CT27","title":"Network algorithms: shortest routes","steps":[{"key":"HOME","screen":"Add Calculator · calculator-assisted","say":"Use the calculator for distance sums. Record the route choices yourself."},{"key":"WRITE","screen":"A=0; B=∞; C=∞; D=∞","say":"For Dijkstra’s algorithm, begin at the source and set every other tentative distance to infinity."},{"key":"TYPE","screen":"Example links: AB=2, AC=5, BC=1, BD=5, CD=2","say":"Settle the smallest unsettled distance. From B, update C to three and D to seven."},{"key":"ENTER","screen":"From C, update D to 3+2=5","say":"Keep a new distance only if it is smaller. Trace the predecessors back from D to recover the route."}],"try":{"prompt":"Undirected links have weights AB=4, AC=7, BC=1, BD=6 and CD=3. What is the shortest distance from A to D?","answer":8,"explain":"A–B–C–D costs 4+1+3=8. Both A–B–D and A–C–D cost 10.","alternatives":[]}},{"id":"CT28","title":"Create lists and frequency tables","steps":[{"key":"HOME","screen":"Add Lists & Spreadsheet","say":"Name one column for the values and one for frequencies. Use the name cells above the first data row."},{"key":"TYPE","screen":"val: 1,2,3  ·  freq: 2,4,1","say":"Put each frequency on the same row as its value. Here the score two occurs four times."},{"key":"MENU","screen":"Statistics → Stat Calculations → One-Variable Statistics","say":"Choose one list. Select the value list for X1 and the frequency list in its own field."},{"key":"READ","screen":"n=7","say":"The total count is the sum of the frequencies, not the number of data rows."}],"try":{"prompt":"Values 2, 5, and 8 occur with respective frequencies 3, 6, and 2. What total sample size should your frequency calculation report?","answer":11,"explain":"Add the frequencies: 3+6+2=11.","alternatives":[]}},{"id":"CT29","title":"One-variable statistics and standard deviation","steps":[{"key":"HOME","screen":"Add Lists & Spreadsheet","say":"Name a list and enter one data value per row."},{"key":"MENU","screen":"Statistics → Stat Calculations → One-Variable Statistics","say":"Select one list and choose its name for X1. Leave frequencies at one if no frequency list is needed."},{"key":"ENTER","screen":"Data: 2,4,6 · x̄=4 · sₓ=2 · σₓ≈1.633","say":"Read the requested standard deviation. S uses a divisor of n minus one; sigma uses a divisor of n."},{"key":"CHECK","screen":"n = 3","say":"Check sample size and units before recording the result. Standard deviation uses the same units as the data."}],"try":{"prompt":"The values 3, 7 and 11 are a sample. Find the sample standard deviation.","answer":4,"explain":"The mean is 7 and the sum of squared deviations is 32. Divide by n−1=2, then take the square root.","alternatives":[]}},{"id":"CT30","title":"Box plots, outliers and histograms","steps":[{"key":"HOME","screen":"Lists & Spreadsheet: marks = 1,2,2,3,4,5,6,8,20","say":"Name the list and enter the raw data. Add a Data & Statistics page in the same problem."},{"key":"AXIS","screen":"Select marks on the horizontal axis","say":"Choose the named list on the axis. The page initially displays the raw values as a dot plot."},{"key":"MENU","screen":"Plot Types → Box Plot","say":"Use the box to read quartiles and the median. A modified box plot draws outliers separately."},{"key":"MENU","screen":"Plot Types → Histogram","say":"For a histogram, check the bins. Bin boundaries can change the display, even though the data are unchanged."}],"try":{"prompt":"For a data set with Q1=3 and Q3=7, the modified box plot uses a 1.5×IQR upper fence. Which value is above that fence?","answer":"14","explain":"IQR is 4, so the upper fence is 7+1.5×4=13. Only 14 is strictly above it.","alternatives":[],"choices":["12","13","14"]}},{"id":"CT31","title":"Pearson correlation and linear regression","steps":[{"key":"Lists & Spreadsheet","screen":"xdata: 1, 2, 3, 4\nydata: 3, 2, 8, 7","say":"Name two columns and put each pair on the same row."},{"key":"Menu → Statistics → Stat Calculations","screen":"Linear Regression (a+bx)","say":"Choose the a plus b x model. This version reports Pearson r with the coefficients."},{"key":"Select lists → OK","screen":"X List: xdata\nY List: ydata","say":"Use x data as the predictor and y data as the response. Leave frequency at one."},{"key":"Read results","screen":"a = 0.5   b = 1.8   r ≈ 0.789352","say":"The fitted line is zero point five plus one point eight x. Pearson r measures the direction and strength of the linear association."}],"try":{"prompt":"For x = (1, 2, 3, 4) and y = (3, 2, 8, 7), use the fitted line to predict y at x = 2.5.","answer":"5","explain":"Substitute x = 2.5 into 0.5 + 1.8x. The location is inside the observed x range.","alternatives":[]}},{"id":"CT32","title":"Quadratic and other nonlinear regression","steps":[{"key":"Lists & Spreadsheet","screen":"xdata: 0, 1, 2, 3\nydata: 5, 4, 7, 14","say":"Enter each input and response as a matched pair."},{"key":"Menu → Statistics → Stat Calculations","screen":"Quadratic Regression","say":"Use a quadratic model when the shape calls for it. A high R squared does not alone justify a model."},{"key":"Select lists → OK","screen":"X List: xdata\nY List: ydata","say":"Set the measured input as x and the output as y. Keep the default unit frequency."},{"key":"Read a, b, c","screen":"y = 2x² − 3x + 5","say":"The coefficients displayed fit the model a x squared plus b x plus c. Evaluate that fitted equation to predict."}],"try":{"prompt":"For x = (0, 1, 2, 3) and y = (5, 4, 7, 14), what does the quadratic model predict at x = 1.5?","answer":"5","explain":"Evaluate 2(1.5)² − 3(1.5) + 5 = 5.","alternatives":[]}},{"id":"CT33","title":"Exponential regression and growth factors","steps":[{"key":"Lists & Spreadsheet","screen":"xdata: 0, 1, 2, 3\nydata: 4, 6, 9, 13.5","say":"Use matched columns. The measured outputs are positive."},{"key":"Menu → Statistics → Stat Calculations","screen":"Exponential Regression","say":"Choose Exponential Regression, then supply the x and y columns."},{"key":"Select lists → OK","screen":"y = a · bˣ\na = 4; b = 1.5","say":"In this model a is the value at x equals zero, and b is the factor per unit of x."},{"key":"Read growth factor","screen":"(1.5 − 1) × 100 = 50","say":"Subtract one from the growth factor before converting it to a percentage."}],"try":{"prompt":"A fitted exponential model is y = 7 · 1.12ˣ. What is its percentage growth per unit increase in x? Enter a number without the percent sign.","answer":"12","explain":"The multiplier is 1.12. Subtract 1 and multiply by 100.","alternatives":[]}},{"id":"CT34","title":"Linearizing data with logarithms","steps":[{"key":"Lists & Spreadsheet","screen":"xdata: 0, 1, 2, 3\nydata: 2, 6, 18, 54","say":"Enter paired columns. Only positive response values have real logarithms."},{"key":"Name column lny → formula cell","screen":"ln(ydata)","say":"Put the logarithm of the y list in the new column formula cell, not in its column name."},{"key":"Menu → Statistics → Stat Calculations","screen":"Linear Regression (mx+b)\nX: xdata  Y: lny","say":"Regress log y on x. Do not use the original y list as the response."},{"key":"Convert back","screen":"ln y = 1.09861x + 0.693147\ny = 2 · 3ˣ","say":"Exponentiate both sides. The growth factor is e to the slope and the value at zero is e to the intercept."}],"try":{"prompt":"After regression on an ln(y) column, the intercept is 1.386294361. What is the model’s predicted y at x = 0, to 2 decimal places?","answer":"4","explain":"The intercept is ln(y) at x = 0, so y = exp(1.386294361) ≈ 4.","alternatives":[]}},{"id":"CT35","title":"Spearman rank correlation","steps":[{"key":"Rank first · assisted","screen":"x: 10, 20, 30, 40\ny: 9, 7, 7, 2","say":"Rank each variable separately from low to high. Keep the ranks on the original paired rows."},{"key":"Lists & Spreadsheet","screen":"rx: 1, 2, 3, 4\nry: 4, 2.5, 2.5, 1","say":"The two tied sevens share the average of ranks two and three."},{"key":"Menu → Statistics → Stat Calculations","screen":"Linear Regression (a+bx)\nX: rx  Y: ry","say":"Select the rank lists, not the measurements. Read Pearson r from the results."},{"key":"Read r","screen":"rₛ ≈ −0.948683","say":"Pearson correlation of paired ranks is Spearman correlation. The rank preparation was manual."}],"try":{"prompt":"Using ascending ranks, what is Spearman rₛ for x = (1, 2, 3, 4) and y = (12, 9, 6, 3)?","answer":"-1","explain":"The ranks are (1, 2, 3, 4) and (4, 3, 2, 1), so rank association is perfectly negative.","alternatives":[]},"assisted":true},{"id":"CT36","title":"Discrete random variables and expectation","steps":[{"key":"Check distribution · assisted","screen":"x: 0, 2, 5\nP(X = x): 0.30, 0.40, 0.30","say":"Check that the probabilities total one before finding a weighted mean."},{"key":"Calculator","screen":"0*0.30+2*0.40+5*0.30","say":"Multiply each value by its own probability, then add those products."},{"key":"Enter","screen":"2.3","say":"The expectation is a long-run average. It need not be a possible individual outcome."}],"try":{"prompt":"X takes 1, 4 and 8 with respective probabilities 0.2, 0.5 and 0.3. Find E(X).","answer":"4.6","explain":"Compute 1(0.2) + 4(0.5) + 8(0.3) = 4.6.","alternatives":[]},"assisted":true},{"id":"CT37","title":"Binomial: exact probability","steps":[{"key":"Calculator → Menu → Probability","screen":"Distributions → Binomial Pdf","say":"Choose the exact probability tool for one count."},{"key":"Enter n, p, x","screen":"binomPdf(9,0.3,3)","say":"Supply the number of trials, chance of success on each trial, and exact number of successes, in that order."},{"key":"Enter","screen":"P(X = 3) ≈ 0.266828","say":"This is exactly three successes, not three or fewer."}],"try":{"prompt":"For X ~ Bin(10, 0.2), find P(X = 2) to 4 decimal places.","answer":"0.3020","explain":"binomPdf(10,0.2,2) returns about 0.301989888.","alternatives":["0.302"]}},{"id":"CT39","title":"Normal: interval and tail probabilities","steps":[{"key":"Calculator → Menu → Probability","screen":"Distributions → Normal Cdf","say":"Choose Normal Cdf to get area under the normal curve, not a density at a single value."},{"key":"Enter bounds, mean, SD","screen":"normCdf(18,23,20,2)","say":"Use the lower and upper endpoints in that order. Use two for the standard deviation, not four for the variance."},{"key":"Enter","screen":"P(18 < X < 23) ≈ 0.774538","say":"The area between these two bounds is about zero point seven seven five. For a one-sided tail, use infinity or the complementary tail."}],"try":{"prompt":"A normal variable has mean 20 and standard deviation 2. Find P(X > 23) to 4 decimal places.","answer":"0.0668","explain":"Use normCdf(23,∞,20,2) or 1 minus the area below 23.","alternatives":[]}},{"id":"CT40","title":"Inverse normal: percentiles and cutoffs","steps":[{"key":"Identify left-tail area","screen":"Bottom 75% → 0.75","say":"Inverse Normal starts from probability and returns a value. Use the left-tail probability for a percentile."},{"key":"Calculator → Menu → Probability","screen":"Distributions → Inverse Normal","say":"Use the inverse command rather than Normal Cdf."},{"key":"Enter area, mean, SD","screen":"invNorm(0.75,32,4)","say":"Input zero point seven five, then the mean and standard deviation."},{"key":"Enter","screen":"x ≈ 34.697959","say":"A percentile above fifty should be above the mean."}],"try":{"prompt":"A normal population has mean 50 and standard deviation 5. Find the cutoff with 10% above it, to 2 decimal places.","answer":"56.41","explain":"The right-tail area is 0.10, so use invNorm(0.90,50,5).","alternatives":[]}},{"id":"CT41","title":"Solve an unknown normal parameter","steps":[{"key":"Standardise · assisted","screen":"P(X < 20) = 0.10, σ = 5","say":"We know a percentile and spread but not the mean. Obtain the matching standard normal z-score."},{"key":"Calculator → Probability → Distributions","screen":"invNorm(0.10,0,1) ≈ −1.28155","say":"Use zero and one for the standard normal, not twenty and five."},{"key":"Calculator","screen":"μ = 20 − 5z ≈ 26.4078","say":"Rearrange z equals twenty minus mu, divided by five. Use the unrounded stored answer."}],"try":{"prompt":"A normal distribution has SD 4 and 25% of values below 20. Find the mean to 2 decimal places.","answer":"22.70","explain":"Solve (20 − μ)/4 = invNorm(0.25,0,1).","alternatives":["22.7"]},"assisted":true},{"id":"CT42","title":"Poisson: exact and cumulative probabilities","steps":[{"key":"Set mean for time window","screen":"2 per hour → λ = 4 for 2 hours","say":"First scale the mean to match the length of the interval, assuming the rate is constant."},{"key":"Calculator → Probability → Distributions","screen":"Poisson Pdf\npoissPdf(4,1) ≈ 0.073263","say":"Use Poisson P D F for exactly one event. Lambda comes first."},{"key":"Calculator → Probability → Distributions","screen":"Poisson Cdf\npoissCdf(4,0,1) ≈ 0.091578","say":"At most one event includes both zero and one. Use inclusive bounds zero and one with P C D F."}],"try":{"prompt":"Events occur at a constant Poisson rate of 2 per hour. Find P(at most 2 events in 90 minutes) to 4 decimal places.","answer":"0.4232","explain":"Scale λ to 3 and include counts 0, 1 and 2 in poissCdf(3,0,2).","alternatives":[]}},{"id":"CT43","title":"Sampling means and the central limit theorem","steps":[{"key":"Calculate standard error","screen":"σ/√n = 15/√25 = 3","say":"The sampling distribution is of sample means. Its standard deviation is three, not fifteen."},{"key":"Calculator → Probability → Distributions","screen":"Normal Cdf\nLower = 54.5; Upper = ∞","say":"For the upper tail, use the threshold as the lower bound and positive infinity as the upper bound."},{"key":"Enter mean and SE","screen":"normCdf(54.5,∞,50,3) ≈ 0.066807","say":"The mean stays at fifty. For a normal population this sampling distribution is exactly normal; otherwise justify the normal approximation."}],"try":{"prompt":"An independent sample of 25 comes from a normal population with mean 50 and SD 15. Find P(X̄ > 53), to 4 decimal places.","answer":"0.1587","explain":"X̄ has SD 15/√25 = 3, so the right-tail z-score is 1.","alternatives":[]}},{"id":"CT44","title":"Random simulation and repeated trials","steps":[{"key":"Calculator → Menu → Probability","screen":"Random → Integer","say":"Model each die roll with a random integer from one through six."},{"key":"Enter command","screen":"randInt(1,6,12)","say":"The third argument requests a list of twelve simulated rolls. A different run can give a different list."},{"key":"Tally then divide","screen":"4 sixes out of 12 → 4/12","say":"Count only the result of interest and divide by all trials. Compare with, but do not replace, the theoretical probability."}],"try":{"prompt":"One simulated list was {2,6,1,3,6,4,5,5,6,3,2,4}. What proportion of the twelve rolls are sixes?","answer":"0.25","explain":"There are three sixes, so the relative frequency is 3/12 = 0.25.","alternatives":[]}},{"id":"CT45","title":"One-sample z-test: known population SD","steps":[{"key":"Write hypotheses","screen":"H₀: μ = 80\nH₁: μ > 80","say":"A greater-than alternative is right-tailed. A population standard deviation is known here."},{"key":"Menu → Statistics → Stat Tests","screen":"z Test → Stats","say":"Choose summary statistics because no raw data list is supplied."},{"key":"Fill dialog","screen":"μ₀=80, σ=12, x̄=84, n=36\nAlternative: μ > μ₀","say":"Check the null mean, population standard deviation, observed sample mean, sample size and direction."},{"key":"OK → read p","screen":"z = 2\np ≈ 0.0227501","say":"Compare the one-sided p value with alpha. Reject the null at five percent in this case."}],"try":{"prompt":"For H₀: μ = 50 versus H₁: μ < 50, known σ = 8, n = 16 and x̄ = 47, find the p-value to 4 decimal places.","answer":"0.0668","explain":"z = (47 − 50)/(8/√16) = −1.5. The lower-tail area is about 0.0668072.","alternatives":[]}},{"id":"CT46","title":"One-sample and two-sample t-tests","steps":[{"key":"Write hypotheses","screen":"H₀: μ = 50\nH₁: μ > 50","say":"Use t when the population standard deviation is unknown and the sampling conditions are met."},{"key":"Menu → Statistics → Stat Tests","screen":"t Test → Stats","say":"Use t Test for one sample. Choose Stats for the supplied summaries."},{"key":"Fill dialog then OK","screen":"μ₀=50, x̄=56, sₓ=6, n=9\nAlternative: μ > μ₀","say":"Enter the sample standard deviation, not a population standard deviation."},{"key":"Read t, df and p","screen":"t = 3, df = 8, p ≈ 0.00854","say":"Read the test statistic, degrees of freedom, and p value. The right-tail probability is about zero point zero zero eight five four."},{"key":"Independent two-sample variation","screen":"Stat Tests → 2-Sample t Test\nPooled: No","say":"For two independent groups use two-sample t Test. Select unpooled unless equal variances are justified. For paired data, use one sample of differences instead."}],"try":{"prompt":"A one-sample t-test uses μ₀ = 50, x̄ = 53, s = 6, n = 16, and alternative μ > 50. Find p to 4 decimal places.","answer":"0.0320","explain":"The test statistic is 2 with 15 degrees of freedom. Use the upper tail.","alternatives":["0.032"]}},{"id":"CT47","title":"Chi-square test of independence","steps":[{"key":"Calculator → Matrix template","screen":"[18  12]\n[ 8  22]","say":"Create a two by two matrix of the observed counts only and store it with a name such as obs. Do not add total rows or columns."},{"key":"Menu → Statistics → Stat Tests","screen":"χ² 2-way Test\nObserved Matrix: obs","say":"Use the two-way test for association between two categorical variables."},{"key":"OK → read result","screen":"χ² ≈ 6.78733, df = 1, p ≈ 0.00918","say":"Check the expected counts before using the result. Here they are thirteen and seventeen in both rows."},{"key":"Compare with α = 0.05","screen":"Reject independence","say":"A small p value provides evidence of association, not a causal relationship."}],"try":{"prompt":"Observed counts are [[14,6],[6,14]]. Find the Pearson chi-square statistic, without continuity correction.","answer":"6.4","explain":"All expected counts equal 10. Four identical contributions of (14−10)²/10 add to 6.4.","alternatives":[]}},{"id":"CT48","title":"Chi-square goodness-of-fit","steps":[{"key":"Lists & Spreadsheet","screen":"obs: 11, 19, 15\nexpected: 15, 15, 15","say":"Use one observed and one expected list in the same category order."},{"key":"Menu → Statistics → Stat Tests","screen":"χ² GOF Test\nObserved List: obs; Expected List: expected","say":"Choose goodness of fit for one categorical variable with specified expected proportions."},{"key":"Enter df → OK","screen":"df = 2\nχ² ≈ 2.13333, p ≈ 0.344154","say":"There are three categories and no parameters estimated here, so degrees of freedom are two."},{"key":"Compare with α = 0.05","screen":"Do not reject H₀","say":"The p value is not small enough to reject equal proportions. That does not prove they are equal."}],"try":{"prompt":"Under equal proportions, observed counts are (14, 23, 23). Find the goodness-of-fit χ² statistic.","answer":"2.7","explain":"Expected frequencies are each 20. Sum (36 + 9 + 9)/20.","alternatives":[]}},{"id":"CT49","title":"Confidence intervals: z and t","steps":[{"key":"Choose interval family","screen":"Known population σ → z Interval","say":"Use z for a known population standard deviation; use a t interval for an unknown one, with the sample standard deviation."},{"key":"Menu → Statistics → Confidence Intervals","screen":"z Interval → Stats","say":"Choose summary-statistic entry."},{"key":"Fill dialog then OK","screen":"σ=4, x̄=30, n=64, C Level=0.95","say":"Input the sample size and confidence level as a decimal."},{"key":"Read endpoints","screen":"(29.0200, 30.9800)","say":"These endpoints estimate a population mean, not the spread of individual measurements."},{"key":"Unknown population SD","screen":"Confidence Intervals → t Interval\nUse sₓ in place of σ","say":"When you do not know the population standard deviation, choose t Interval and enter the sample standard deviation. Do not substitute the sample deviation in the z dialog."}],"try":{"prompt":"Find the lower endpoint of the 90% z interval when x̄ = 22, known σ = 3 and n = 36. Round to 2 decimal places.","answer":"21.18","explain":"The standard error is 3/√36 = 0.5, so the lower endpoint is 22 − 1.64485(0.5).","alternatives":[]}},{"id":"CT50","title":"Exact binomial hypothesis test","steps":[{"key":"Write null and alternative","screen":"H₀: p = 0.5; H₁: p > 0.5\nn = 12; observed x = 9","say":"The observed count and all more extreme counts define the tail. Here it is the upper tail."},{"key":"Calculator → Probability → Distributions","screen":"Binomial Cdf\nbinomCdf(12,0.5,9,12)","say":"Under the null, use twelve trials and probability one half. Include nine through twelve."},{"key":"Enter → compare with α","screen":"p ≈ 0.0730 > 0.05","say":"Do not reject the null at five percent. The null probability is an input; the test p value is the output."}],"try":{"prompt":"In 8 trials, 1 succeeds. For H₀: p = 0.5 versus H₁: p < 0.5, find the exact p-value to 4 decimal places.","answer":"0.0352","explain":"The lower tail includes counts 0 and 1. binomCdf(8,0.5,0,1) gives 9/256.","alternatives":[]}},{"id":"CT51","title":"Numerical derivative and tangent line","steps":[{"key":"Calculator → Menu → Calculus","screen":"Numerical Derivative at a Point","say":"The non-CAS template evaluates a slope at a point, not a symbolic derivative."},{"key":"Fill derivative template","screen":"d/dx (x³+x) at x=2","say":"Set the variable and evaluation point, then enter the expression. Press Enter."},{"key":"Calculate point","screen":"f′(2) = 13; f(2) = 10","say":"Find the function value separately. The slope is thirteen and the point is two, ten."},{"key":"Use point-slope form","screen":"y − 10 = 13(x − 2)","say":"Write the tangent line with both the slope and the point on the curve."}],"try":{"prompt":"For f(x) = x³ + x, find the y-intercept of its tangent line at x = 2.","answer":"-16","explain":"The tangent is y − 10 = 13(x − 2), giving y = 13x − 16.","alternatives":[]}},{"id":"CT52","title":"Stationary points via numerical derivative","steps":[{"key":"Graphs · assisted","screen":"f₁(x) = x³ − 3x","say":"Plot the curve and use a window that shows both turning points."},{"key":"Menu → Analyze Graph","screen":"Maximum near x = −1\nMinimum near x = 1","say":"Bracket each turning point separately. Use the graph to classify the type."},{"key":"Calculator → Numerical Derivative at a Point","screen":"Evaluate at −1 and 1","say":"Both gradients are zero. The tool checks one x value at a time; it does not give the derivative formula."},{"key":"Read coordinates","screen":"(−1, 2) local max\n(1, −2) local min","say":"If solving algebraically with a numerical solver, enter the derivative you found by hand, not the original function."}],"try":{"prompt":"For f(x) = x³ − 12x, what is the x-coordinate of its local maximum?","answer":"-2","explain":"The stationary x-values are ±2. At x = −2 the slope changes from positive to negative.","alternatives":[]},"assisted":true},{"id":"CT53","title":"Kinematics: displacement versus total distance","steps":[{"key":"Find velocity zero","screen":"v(t) = 2t − 6, t ∈ [0,5]\nv(t) = 0 at t = 3","say":"Velocity changes direction at three seconds. That is where signed and total distance calculations differ."},{"key":"Calculator → Menu → Calculus","screen":"Numerical Definite Integral\n∫₀⁵ (2t − 6) dt","say":"Use the signed velocity for displacement. Make sure the integration variable matches t."},{"key":"Integrate speed","screen":"∫₀⁵ |2t − 6| dt = 13","say":"Integrate absolute velocity for distance, or add the magnitudes of the signed integrals on either side of the zero."}],"try":{"prompt":"Velocity is v(t) = 3t − 6 m/s for 0 ≤ t ≤ 4. Find the total distance in metres.","answer":"12","explain":"Velocity changes sign at t = 2. Each of the two speed triangles contributes 6 m.","alternatives":[]}},{"id":"CT54","title":"Numerical definite integral and signed area","steps":[{"key":"Calculator → Menu → Calculus","screen":"Numerical Definite Integral","say":"Select the integral template on the non-CAS Calculator page."},{"key":"Fill in limits and expression","screen":"Lower: 0; Upper: 4\nIntegrand: x − 3; variable: x","say":"The variable in the differential must match the variable used in the integrand."},{"key":"Enter","screen":"∫₀⁴ (x − 3) dx = −4","say":"The graph is below the axis from zero to three and above it from three to four; signed contributions partially cancel."}],"try":{"prompt":"Find the signed integral of f(x) = x − 4 from 0 to 6.","answer":"-6","explain":"The signed areas are −8 and +2. Total geometric area would be 10, not −6.","alternatives":[]}},{"id":"CT55","title":"Area between two curves","steps":[{"key":"Graphs → Analyze Graph","screen":"Intersection: f₁(x)=4, f₂(x)=x²\nx = −2 and x = 2","say":"Graph both functions and locate each intersection with its own bounds."},{"key":"Check ordering","screen":"At x = 0: 4 > 0","say":"The constant curve sits above the parabola between the intersections."},{"key":"Calculator → Calculus","screen":"Numerical Definite Integral\n∫₋₂² (4 − x²) dx ≈ 10.6667","say":"Use upper minus lower with the intersection x values as integration limits."}],"try":{"prompt":"Find the bounded area between y = 9 and y = x².","answer":"36","explain":"Integrate the upper-minus-lower function 9 − x² from −3 to 3.","alternatives":[]}},{"id":"CT56","title":"Trapezoidal rule and approximation","steps":[{"key":"Choose spacing · assisted","screen":"x: 0, 1, 2\nf(x) = x²: 0, 1, 4","say":"Two equal panels across zero to two have width one. List both endpoint values and the interior value."},{"key":"Calculator","screen":"(1/2)*(0+2*1+4)","say":"Multiply the interior ordinate by two. Each endpoint is used once."},{"key":"Enter → compare","screen":"T₂ = 3\nIntegral = 8/3","say":"This is a trapezoid estimate, not the numerical integral of the formula. For this convex graph the estimate is too large."}],"try":{"prompt":"Use the trapezoidal rule for equally spaced x = 0, 1, 2, 3 with ordinates f(x) = 1, 2, 5, 10. Find the estimated integral.","answer":"12.5","explain":"With h = 1, the estimate is (1/2)(1 + 2·2 + 2·5 + 10) = 12.5.","alternatives":[]},"assisted":true},{"id":"CT57","title":"Volumes of revolution","steps":[{"key":"Set up cross-sectional area","screen":"y = 2x on [0,1], rotated about x-axis","say":"The radius is the vertical distance from the x-axis. The area of a disk is pi times radius squared."},{"key":"Calculator → Menu → Calculus","screen":"Numerical Definite Integral\n∫₀¹ π(2x)² dx","say":"Put the full disk area in the integrand and enter the same limits as the x interval."},{"key":"Enter","screen":"V = 4π/3 ≈ 4.18879","say":"Report cubic units. If the region has a hole, subtract the squared inner radius from the squared outer radius."}],"try":{"prompt":"Rotate the region under y = 3x for 0 ≤ x ≤ 2 around the x-axis. Find volume to 3 decimal places.","answer":"75.398","explain":"V = ∫₀² π(3x)² dx = 24π.","alternatives":["24π","24pi"]}},{"id":"CT58","title":"Euler method for a first-order ODE","steps":[{"key":"Write recurrence · assisted","screen":"y′ = x + y; y(0) = 2; h = 0.2","say":"Use the current x and y to find the slope. This is explicit Euler, not an exact solution."},{"key":"Calculator · first step","screen":"y₁ = 2 + 0.2(0 + 2) = 2.4\nx₁ = 0.2","say":"Multiply the slope by the step size and add it to y. Advance x by the same step size."},{"key":"Calculator · second step","screen":"y₂ = 2.4 + 0.2(0.2 + 2.4) = 2.92","say":"Now use the new x and y values to recompute the slope at the start of this second step."}],"try":{"prompt":"For y′ = x + y and y(0) = 2, use Euler’s method with h = 0.1. Estimate y(0.2).","answer":"2.43","explain":"The intermediate state is (0.1,2.2), so the second slope is 2.3 and the increment is 0.23.","alternatives":[]},"assisted":true},{"id":"CT59","title":"Coupled ODEs, slopes and phase paths","steps":[{"key":"Write both updates · assisted","screen":"x′=x+y; y′=−x; (x₀,y₀)=(2,1)\nh=0.1","say":"Start by calculating both rates from the same old pair."},{"key":"Calculator · first step","screen":"rates: (3,−2)\nnew pair: (2.3,0.8)","say":"Add one tenth of each rate to its corresponding variable. Do not use the new x to calculate the y update."},{"key":"Calculator · second step","screen":"rates: (3.1,−2.3)\nnew pair: (2.61,0.57)","say":"Recompute both rates using the intermediate state before updating either variable."},{"key":"Phase plane","screen":"(2,1) → (2.3,0.8) → (2.61,0.57)","say":"Plot each x and y pair. Time orders the points but is not one of the phase plane axes."}],"try":{"prompt":"Using explicit Euler with h = 0.2 for x′ = x + y and y′ = −x, starting at (2,1), what is y after two steps?","answer":"0.08","explain":"State after step one is (2.6,0.6). Then y decreases by 0.2×2.6 = 0.52.","alternatives":[]},"assisted":true}];
